@Override // net.micode.notes.ui.LocalizedActivity, android.app.Activity
protected void onCreate(Bundle savedInstanceState) {
    super.onCreate(savedInstanceState);
    setContentView(R.layout.note_edit);
    Intent noteIntent = getIntent();
    if (savedInstanceState != null && savedInstanceState.getLong("android.intent.extra.UID", 0L) > 0) {
        noteIntent = new Intent("android.intent.action.VIEW");
        noteIntent.putExtra("android.intent.extra.UID", savedInstanceState.getLong("android.intent.extra.UID"));
    }
    if (!initActivityState(noteIntent)) {
        finish();
    } else {
        initResources();
    }
}
